css:
.section-title {
        font-weight: bold;
        margin-top: 15px;
        text-decoration: underline;
    }
    .infraction-box {
        border: 1px solid black;
        padding: 10px;
        margin-top: 10px;
    }
    .checkbox {
        margin-right: 15px;
        display: inline-block;
        width: 45%;
    }
    .ack-section {
        border-top: 2px dashed #000;
        margin-top: 30px;
        padding-top: 15px;
    }
    .highlight {
        font-weight: bold;
    }

html:
{% if letter_head and not no_letterhead -%}
  <div class="letter-head">{{ letter_head }}</div>
{%- endif %}

<p><strong>REF NO:</strong> {{ doc.name or "" }}</p>

<h3><strong class="highlight">Employee Warning Notice ({{ doc.letter_type or ""}})</strong></h3>

<p><strong class="highlight">EMPLOYEE NAME:</strong> {{ doc.employee_name or "" }}&nbsp;&nbsp;&nbsp;&nbsp; 
<strong>Date of Warning:</strong> {{ doc.get_formatted("posting_date") or "" }}</p>

<p><strong class="highlight">Employee Code:</strong> {{ doc.employee or "" }}&nbsp;&nbsp;&nbsp;&nbsp; 
<strong class="highlight">Designation:</strong> {{ doc.designation or "" }}&nbsp;&nbsp;&nbsp;&nbsp; 
<strong class="highlight">Location:</strong> {{ doc.location or "" }}</p>

<div class="section-title"><strong>NATURE OF INFRACTION</strong></div>

<div class="infraction-box">
  <div class="checkbox">
    {{ doc.nature_of_infraction or "" }}
  </div>
  <div class="checkbox">
    <strong>Other:</strong> {{ doc.other_infraction_if_any or "" }}
  </div>
</div>

<p><strong>DETAILS OF INFRACTION:</strong> {{ doc.details_of_infraction or "" }} </p>

<br>

<p>
Should you repeat any such offence in future or commit any other misconduct, 
you will be subjected to a disciplinary action as per Qatar Labor law which will lead to immediate release from duty and 
<ins>repatriation</ins> to your country of origin 
<ins>without notice and without payment of the end of service</ins>.
</p>

<!-- SIGNATURE BLOCK -->
<div style="border: 1px solid #000; padding: 10px; margin-top: 30px;">

  <table style="width: 100%; border-collapse: collapse; font-size: 10px; text-align:center;">
    <tr style="border-bottom-color: white;">
      <!-- Line Manager -->
      <td style="border-bottom-color: white;">
        {% for child in doc.workflow_status %}
          {% if "Line Manager Approval" == child.workflow_states %}
            {% set user_doc = frappe.get_doc("User", child.approved_by) %}
            <span>{{ user_doc.full_name }}</span><br>
            {% set sig1 = frappe.db.get_value('User Signature', child.approved_by, 'signature') %}
            {% if sig1 %}
              {%- set file_url = frappe.db.get_value("File", {"file_url": sig1}, "file_url") %}
              <img src="{{ file_url }}" alt="Signature" height="40">
            {% endif %}
          {% endif %}
        {% endfor %}
      </td>

      <!-- Division Head -->
      <td style="border-bottom-color: white;">
        {% for child in doc.workflow_status %}
          {% if "Division Head Approval" == child.workflow_states %}
            {% set user_doc = frappe.get_doc("User", child.approved_by) %}
            <span>{{ user_doc.full_name }}</span><br>
            {% set sig1 = frappe.db.get_value('User Signature', child.approved_by, 'signature') %}
            {% if sig1 %}
              {%- set file_url = frappe.db.get_value("File", {"file_url": sig1}, "file_url") %}
              <img src="{{ file_url }}" alt="Signature" height="40">
            {% endif %}
          {% endif %}
        {% endfor %}
      </td>
    </tr>
    <tr>
      <td><b>Line Manager:</b><b>______________________</b></td>
      <td><b>Division Head:</b><b>______________________</b></td>
    </tr>
  </table>


  <table style="width: 100%; border-collapse: collapse; font-size: 10px; text-align:center;">
    <tr style="border-bottom-color: white;">
      <!-- HR Manager -->
      <td style="border-bottom-color: white;">
        {% for child in doc.workflow_status %}
          {% if "HR Manager Approval" == child.workflow_states %}
            {% set user_doc = frappe.get_doc("User", child.approved_by) %}
            <span>{{ user_doc.full_name }}</span><br>
            {% set sig1 = frappe.db.get_value('User Signature', child.approved_by, 'signature') %}
            {% if sig1 %}
              {%- set file_url = frappe.db.get_value("File", {"file_url": sig1}, "file_url") %}
              <img src="{{ file_url }}" alt="Signature" height="40">
            {% endif %}
          {% endif %}
        {% endfor %}
      </td>

      <!-- COO -->
      <td style="border-bottom-color: white;">
        {% for child in doc.workflow_status %}
          {% if "Approved" == child.workflow_states %}
            {% set user_doc = frappe.get_doc("User", child.approved_by) %}
            <span>{{ user_doc.full_name }}</span><br>
            {% set sig1 = frappe.db.get_value('User Signature', child.approved_by, 'signature') %}
            {% if sig1 %}
              {%- set file_url = frappe.db.get_value("File", {"file_url": sig1}, "file_url") %}
              <img src="{{ file_url }}" alt="Signature" height="40">
            {% endif %}
          {% endif %}
        {% endfor %}
      </td>
    </tr>
    <tr>
      <td><b>HR Manager:</b><b>______________________</b></td>
      <td><b>COO:</b><b>______________________</b></td>
    </tr>
  </table>
</div>

<!-- EMPLOYEE ACKNOWLEDGEMENT -->
<div class="ack-section">
  <h4><strong>EMPLOYEE’S ACKNOWLEDGEMENT OF DISCIPLINARY ACTION</strong></h4>
  <p>
    I acknowledge that I have received a copy of the foregoing Written Warning and that I have had an opportunity to discuss it with my supervisor or a designated manager and accept the action as above.
  </p>
  <br><br>
  <strong>Employee’s Signature:</strong> ______________________
</div>

<!-- FOOTER -->
<div id="footer-html" class="visible-pdf">
  {% if footer and not no_letterhead %}
    <div id="letter-head-footer">
      {{ footer }}
    </div>
  {% endif %}
</div>
